using NUnit.Framework;
using UnityEngine;
namespace ShadowVale.Map01.Tests
{
    public sealed class Map02ProgressTests
    {
        [Test]public void ReportsAndDutiesCannotBeSkippedOrCommittedTwice(){var p=new Map02Progress();Assert.IsFalse(p.RequestScoutOrder());Assert.IsTrue(p.ContactConfirmed());Assert.IsFalse(p.ContactConfirmed());Assert.IsTrue(p.StoreCrate());Assert.IsFalse(p.RequestScoutOrder());Assert.IsTrue(p.DeliverMedicine());Assert.IsFalse(p.DeliverMedicine());Assert.IsTrue(p.RequestScoutOrder());Assert.IsFalse(p.ScoutReportConfirmed());Assert.IsTrue(p.FindScout());Assert.IsFalse(p.ScoutReportConfirmed());Assert.IsTrue(p.ShelterScout());Assert.IsTrue(p.ScoutReportConfirmed());}
        [Test]public void PreparationIsFreeOrderButSiegeCannotStartEarly(){var p=Preparing();Assert.IsTrue(p.CheckBoats());Assert.IsFalse(p.BeginEncirclement());Assert.IsTrue(p.MoveSouthStock());Assert.IsFalse(p.BeginEncirclement());Assert.IsTrue(p.GatherWeakGroup());Assert.IsTrue(p.BeginEncirclement());Assert.IsFalse(p.MaySave);Assert.IsTrue(p.FinishEncirclement());Assert.IsFalse(p.FinishEncirclement());Assert.IsTrue(p.MaySave);}
        [Test]public void CivilianMovementIsRequiredInAdditionToFiniteWaves(){var p=Holding();Assert.IsFalse(p.ClearWave(1));Assert.IsTrue(p.ClearWave(0));Assert.IsFalse(p.ClearWave(0));Assert.IsTrue(p.ClearWave(1));Assert.IsFalse(p.ClearWave(2));Assert.IsFalse(p.WithdrawToInnerLane());Assert.IsTrue(p.FrontGroupReachedSafety());Assert.IsTrue(p.WithdrawToInnerLane());}
        [TestCase(0,1)][TestCase(1,0)]public void BothRescueOrdersNeedActualEvacuation(int first,int second){var p=Rescuing();Assert.IsTrue(p.RescueGroup(first));Assert.IsFalse(p.RescueGroup(first));Assert.IsFalse(p.BreakoutOrderConfirmed());Assert.IsTrue(p.RescueGroup(second));Assert.IsFalse(p.RescueGroup(2));Assert.IsTrue(p.BreakoutOrderConfirmed());Assert.IsFalse(p.BoardLastBoat());Assert.IsFalse(p.EvacuateBoats());Assert.IsTrue(p.ClearFireteam());Assert.IsFalse(p.BoardLastBoat());Assert.IsTrue(p.EvacuateBoats());Assert.IsFalse(p.BoardLastBoat());Assert.IsTrue(p.ConfirmHungSacrifice());Assert.IsFalse(p.ConfirmHungSacrifice());Assert.IsTrue(p.BoardLastBoat());Assert.IsFalse(p.BoardLastBoat());Assert.IsFalse(p.ConfirmSafeReception());Assert.IsTrue(p.FinishDeparture());Assert.IsTrue(p.ConfirmSafeReception());Assert.IsFalse(p.ConfirmSafeReception());}
        [Test]public void SaveRoundTripKeepsPreparationAndGroups(){var p=Rescuing();p.RescueGroup(1);var loaded=JsonUtility.FromJson<Map02Progress>(JsonUtility.ToJson(p));Assert.IsTrue(loaded.medicineDelivered&&loaded.crateStored&&loaded.scoutSheltered&&loaded.southStockMoved);Assert.IsFalse(loaded.RescueGroup(1));Assert.IsTrue(loaded.RescueGroup(0));Assert.AreEqual(3,loaded.rescuedGroups);}
        [Test]public void FailureBlocksProgressButCannotUndoCompletion(){var p=Rescuing();Assert.IsTrue(p.Fail("Một người cần bảo vệ đã hy sinh."));Assert.IsFalse(p.Fail("duplicate"));Assert.IsFalse(p.RescueGroup(0));Assert.IsFalse(p.MaySave);p=new Map02Progress{stage=Map02Stage.Complete};Assert.IsFalse(p.Fail("late damage"));}
        static Map02Progress Preparing(){var p=new Map02Progress();p.ContactConfirmed();p.DeliverMedicine();p.StoreCrate();p.RequestScoutOrder();p.FindScout();p.ShelterScout();p.ScoutReportConfirmed();return p;}
        static Map02Progress Holding(){var p=Preparing();p.GatherWeakGroup();p.MoveSouthStock();p.CheckBoats();p.BeginEncirclement();p.FinishEncirclement();return p;}
        static Map02Progress Rescuing(){var p=Holding();p.ClearWave(0);p.ClearWave(1);p.FrontGroupReachedSafety();p.WithdrawToInnerLane();return p;}
    }
}